// @ts-nocheck
/**
 * Fetch the latest benchmark results from fastify/benchmarks and emit
 * `src/data/benchmarks.json` (GET) and `src/data/benchmarks-post.json` (POST)
 * for the benchmarks page.
 *
 * Mirrors the official fastify/website scripts/download-benchmarks.js, adapted
 * for this Astro project:
 *   - Native `fetch` (Node 22+) instead of `undici`.
 *   - Output path matches the existing `src/data/*.json` pattern (gitignored,
 *     regenerated by `npm run build:data`).
 *   - Output schema: `{ date, reference, frameworks: [{ name, tag, test,
 *     repository, requests, version, latency, throughput }] }` — sorted by
 *     `requests` desc, zero-requests entries dropped. `latency` is in ms,
 *     `throughput` in MB/s — both required by the chart surfaces downstream.
 *
 * Falls back to the most recent historical commit when the live results
 * contain `N/A` data (matches upstream behaviour). POST results that are not
 * published yet (404) are not fatal: an empty `frameworks` list is written and
 * the page hides POST. Any other failure fails the build, as it does for GET.
 */
import { writeFile } from "node:fs/promises";
import path from "node:path";
import pino from "pino";
import frameworks from "./frameworks.json" with { type: "json" };

const ROOT = path.resolve(import.meta.dirname, "..");

const SCENARIOS = [
	{
		results: "benchmark-results.json",
		output: path.join(ROOT, "src/data/benchmarks.json"),
		required: true,
	},
	{
		results: "benchmark-results-post.json",
		output: path.join(ROOT, "src/data/benchmarks-post.json"),
		required: false,
	},
];

const RAW_BASE_URL =
	"https://raw.githubusercontent.com/fastify/benchmarks/main";
const GITHUB_BASE_URL = "https://api.github.com/repos/fastify/benchmarks";
const FRAMEWORK_TAGS = frameworks.map(({ tag }) => tag);
const TIMEOUT_MS = 10_000;

const log = pino({
	level: process.env.LOG_LEVEL || "debug",
	msgPrefix: "[download-benchmarks] ",
	transport: {
		target: "pino-pretty",
		options: { colorize: true },
	},
});

export async function downloadBenchmarks() {
	await Promise.all(SCENARIOS.map(downloadScenario));
}

async function downloadScenario({ results, output, required }) {
	let data;
	try {
		data = await downloadBenchmarksFromFile(results);
	} catch (err) {
		if (required || err.status !== 404) throw err;
		log.warn(`Skipping ${results}: ${err.message}`);
		data = { date: "Unknown", reference: 0, frameworks: [] };
	}
	await writeFile(output, `${JSON.stringify(data, null, 2)}\n`);
	log.info(
		`Wrote ${data.frameworks.length} frameworks (reference ${data.reference}) to ${path.relative(ROOT, output)}`,
	);
}

async function downloadBenchmarksFromFile(results) {
	const data = await getJSON(`${RAW_BASE_URL}/${results}`);
	if (isValidBenchmark(data)) {
		const date = await getBenchmarkDate(results);
		return buildBenchmarksJSON(data, date);
	}

	log.warn(`${results} contains \`N/A\` data. Searching for previous revision`);

	const commits = await getCommits(results);
	for (let i = 0; i < commits.length; i++) {
		log.debug(`Checking commit ${commits[i]}`);
		const treeUrl = await getTree(commits[i]);
		const blobUrl = await getUrlFromTree(treeUrl, results);
		const data = await getBlob(blobUrl);
		if (isValidBenchmark(data)) {
			const date = await getBenchmarkDate(results, i);
			return buildBenchmarksJSON(data, date);
		}
	}

	throw new Error(`Unable to find a valid benchmark result in ${results}`);
}

async function getBenchmarkDate(results, offset = 0) {
	const commits = await getJSON(
		`${GITHUB_BASE_URL}/commits?path=${results}&per_page=10`,
	);
	return commits[offset]?.commit?.committer?.date ?? "Unknown";
}

async function getCommits(results) {
	const commits = await getJSON(
		`${GITHUB_BASE_URL}/commits?path=${results}&per_page=10`,
	);
	return commits.map((commit) => commit.sha);
}

async function getTree(commitSha) {
	const commit = await getJSON(`${GITHUB_BASE_URL}/git/commits/${commitSha}`);
	return commit.tree.url;
}

async function getUrlFromTree(treeUrl, results) {
	const tree = await getJSON(treeUrl);
	return tree.tree.find((item) => item.path === results).url;
}

async function getBlob(blobUrl) {
	const blob = await getJSON(blobUrl);
	return JSON.parse(Buffer.from(blob.content, "base64").toString("utf8"));
}

function buildBenchmarksJSON(data, date = "Unknown") {
	const numericRequests = data
		.filter((item) => FRAMEWORK_TAGS.includes(item.name))
		.filter(({ requests }) => !Number.isNaN(Number(requests)))
		.map(({ requests }) => parseInt(requests, 10));

	const reference = numericRequests.length
		? numericRequests.reduce((max, req) => (req > max ? req : max), 0)
		: 0;

	return {
		date,
		reference,
		frameworks: frameworks
			.filter((framework) => data.some(({ name }) => name === framework.tag))
			.map((framework) => {
				const item = data.find(({ name }) => name === framework.tag);
				const requests = parseMetric(item.requests);
				const latency = parseMetric(item.latency);
				const throughput = parseMetric(item.throughput);
				return {
					...framework,
					requests,
					version: item.version,
					latency,
					throughput,
				};
			})
			.filter((f) => f.requests > 0)
			.sort((a, b) => b.requests - a.requests),
	};
}

function parseMetric(value) {
	const parsed = Number(value);
	return Number.isNaN(parsed) ? 0 : parsed;
}

function isValidBenchmark(data) {
	return data
		.filter((item) => FRAMEWORK_TAGS.includes(item.name))
		.some((item) => !Number.isNaN(Number(item.requests)));
}

async function getJSON(url) {
	const headers = {
		"User-Agent": "fastify-website-script",
		Accept: "application/vnd.github+json",
	};
	if (process.env.GH_TOKEN)
		headers.Authorization = `Bearer ${process.env.GH_TOKEN}`;

	const res = await fetch(url, {
		headers,
		signal: AbortSignal.timeout(TIMEOUT_MS),
	});
	if (!res.ok) {
		const err = new Error(`GET ${url} -> ${res.status}`);
		err.status = res.status;
		throw err;
	}
	return res.json();
}
